curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for user in data['members']:
        print(f\"{user['id']} | {user.get('profile',{}).get('real_name','?')} | {user.get('is_admin')} | {user.get('is_owner')} | {user.get('is_app_user')} | created: {user.get('created','?')}\")
else:
    print('Error:', data)
"

curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=public_channel,private_channel&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        print(f\"{ch['id']} | {ch['name']} | {ch['is_private']} | created: {ch.get('created','?')} | is_archived: {ch.get('is_archived')}\")
else:
    print('Error:', data)
"
